//! LLM response schema and validation – upstream `paperless_ai/base_model.py@v3.4.2`.
//!
//! * [`classifier_schema`] = `DocumentClassifierSchema.model_json_schema()` (pydantic 2.12),
//!   byte-exact as embedded JSON (`testdata/classifier_schema.json`, generated by
//!   `tests/parity/pl-ai/gen_golden.py`).
//! * [`openai_tool`] = tool definition that llama_index `OpenAILike.chat_with_tools` sends
//!   (Name `DocumentClassifierSchema`, `strict: false`, `additionalProperties: false`).
//! * [`ClassifierResponse::from_json`] = pydantic validation with `_truncate`
//!   (`mode="before"`: truncate lists/strings to `max_length`).
//! * [`model_to_classification_suggestions`] = function of the same name (check candidate ids).

use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::collections::{BTreeMap, BTreeSet};

/// upstream `MAX_EXISTING_IDS`.
pub const MAX_EXISTING_IDS: usize = 10;
/// upstream `MAX_NEW_NAMES`.
pub const MAX_NEW_NAMES: usize = 8;
/// upstream `MAX_SINGLE_VALUE_NAMES`.
pub const MAX_SINGLE_VALUE_NAMES: usize = 4;
/// upstream `MAX_DATES`.
pub const MAX_DATES: usize = 3;
/// upstream `MAX_TITLE_LENGTH` (= `Document.title` max_length).
pub const MAX_TITLE_LENGTH: usize = 128;

/// Name of the schema / OpenAI tool.
pub const TOOL_NAME: &str = "DocumentClassifierSchema";

const SCHEMA_JSON: &str = include_str!("../testdata/classifier_schema.json");

/// `DocumentClassifierSchema.model_json_schema()` (key order like pydantic).
pub fn classifier_schema() -> Value {
    serde_json::from_str(SCHEMA_JSON).unwrap_or(Value::Null)
}

/// Tool for OpenAI-compatible backends (as llama_index sends it on the wire).
pub fn openai_tool() -> Value {
    let schema = classifier_schema();
    let mut params = Map::new();
    for k in ["properties", "required", "type"] {
        if let Some(v) = schema.get(k) {
            params.insert(k.into(), v.clone());
        }
    }
    params.insert("additionalProperties".into(), Value::Bool(false));
    json!({
        "type": "function",
        "function": {
            "name": TOOL_NAME,
            "description": schema.get("description").cloned().unwrap_or(Value::Null),
            "parameters": Value::Object(params),
            "strict": false,
        }
    })
}

/// Validated, flat LLM response (`DocumentClassifierSchema`).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ClassifierResponse {
    pub title: String,
    pub tags: Vec<String>,
    pub matched_tags: Vec<String>,
    pub tag_ids: Vec<i64>,
    pub correspondents: Vec<String>,
    pub matched_correspondents: Vec<String>,
    pub correspondent_ids: Vec<i64>,
    pub document_types: Vec<String>,
    pub matched_document_types: Vec<String>,
    pub document_type_ids: Vec<i64>,
    pub storage_paths: Vec<String>,
    pub matched_storage_paths: Vec<String>,
    pub storage_path_ids: Vec<i64>,
    pub dates: Vec<String>,
}

/// Validation error (corresponds to pydantic `ValidationError`).
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("invalid LLM response: {0}")]
pub struct SchemaError(pub String);

fn str_list(obj: &Map<String, Value>, key: &str, max: usize) -> Result<Vec<String>, SchemaError> {
    match obj.get(key) {
        None => Ok(Vec::new()),
        Some(Value::Array(a)) => a
            .iter()
            .take(max)
            .map(|v| match v {
                Value::String(s) => Ok(s.clone()),
                _ => Err(SchemaError(format!("{key}: Input should be a valid string"))),
            })
            .collect(),
        Some(_) => Err(SchemaError(format!("{key}: Input should be a valid list"))),
    }
}

fn int_list(obj: &Map<String, Value>, key: &str, max: usize) -> Result<Vec<i64>, SchemaError> {
    match obj.get(key) {
        None => Ok(Vec::new()),
        Some(Value::Array(a)) => a
            .iter()
            .take(max)
            .map(|v| match v {
                // pydantic (lax): int, integral float, numeric string
                Value::Number(n) if n.as_i64().is_some() => Ok(n.as_i64().unwrap_or_default()),
                Value::Number(n) if n.as_f64().is_some_and(|f| f.fract() == 0.0) => {
                    Ok(n.as_f64().unwrap_or_default() as i64)
                }
                Value::String(s) if s.trim().parse::<i64>().is_ok() => Ok(s.trim().parse().unwrap_or_default()),
                _ => Err(SchemaError(format!("{key}: Input should be a valid integer"))),
            })
            .collect(),
        Some(_) => Err(SchemaError(format!("{key}: Input should be a valid list"))),
    }
}

impl ClassifierResponse {
    /// `DocumentClassifierSchema(**data)`: `title` is required; lists/strings are truncated to their maximum length
    /// before validation (upstream `_truncate`).
    pub fn from_value(v: &Value) -> Result<Self, SchemaError> {
        let Value::Object(o) = v else { return Err(SchemaError("Input should be an object".into())) };
        let title = match o.get("title") {
            Some(Value::String(s)) => s.chars().take(MAX_TITLE_LENGTH).collect(),
            Some(_) => return Err(SchemaError("title: Input should be a valid string".into())),
            None => return Err(SchemaError("title: Field required".into())),
        };
        Ok(Self {
            title,
            tags: str_list(o, "tags", MAX_NEW_NAMES)?,
            matched_tags: str_list(o, "matched_tags", MAX_NEW_NAMES)?,
            tag_ids: int_list(o, "tag_ids", MAX_EXISTING_IDS)?,
            correspondents: str_list(o, "correspondents", MAX_SINGLE_VALUE_NAMES)?,
            matched_correspondents: str_list(o, "matched_correspondents", MAX_SINGLE_VALUE_NAMES)?,
            correspondent_ids: int_list(o, "correspondent_ids", MAX_SINGLE_VALUE_NAMES)?,
            document_types: str_list(o, "document_types", MAX_SINGLE_VALUE_NAMES)?,
            matched_document_types: str_list(o, "matched_document_types", MAX_SINGLE_VALUE_NAMES)?,
            document_type_ids: int_list(o, "document_type_ids", MAX_SINGLE_VALUE_NAMES)?,
            storage_paths: str_list(o, "storage_paths", MAX_SINGLE_VALUE_NAMES)?,
            matched_storage_paths: str_list(o, "matched_storage_paths", MAX_SINGLE_VALUE_NAMES)?,
            storage_path_ids: int_list(o, "storage_path_ids", MAX_SINGLE_VALUE_NAMES)?,
            dates: str_list(o, "dates", MAX_DATES)?,
        })
    }

    /// `json.loads(content)` + validation (Ollama path).
    pub fn from_json(s: &str) -> Result<Self, SchemaError> {
        let v: Value = serde_json::from_str(s).map_err(|e| SchemaError(e.to_string()))?;
        Self::from_value(&v)
    }

    /// `model_dump_json()` (pydantic: compact, field order, `ensure_ascii=False`).
    pub fn model_dump_json(&self) -> String {
        serde_json::to_string(self).unwrap_or_default()
    }
}

/// upstream `TaxonomyChoiceDict`.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct TaxonomyChoice {
    pub existing_ids: Vec<i64>,
    pub new_names: Vec<String>,
}

/// upstream `ClassificationSuggestions` (internal form).
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ClassificationSuggestions {
    pub title: String,
    pub tags: TaxonomyChoice,
    pub correspondents: TaxonomyChoice,
    pub document_types: TaxonomyChoice,
    pub storage_paths: TaxonomyChoice,
    pub dates: Vec<String>,
}

/// Allowed candidate ids per category (`tags`, `document_types`, `correspondents`, `storage_paths`).
pub type AllowedIds = BTreeMap<String, BTreeSet<i64>>;

fn py_str_strip_empty(s: &str) -> bool {
    s.trim_matches(crate::compat::py_isspace).is_empty()
}

fn choice(names: &[String], matched: &[String], ids: &[i64], allowed: Option<&BTreeSet<i64>>) -> TaxonomyChoice {
    let mut remaining: Vec<String> = names.iter().filter(|n| !py_str_strip_empty(n)).cloned().collect();
    let mut existing: Vec<i64> = Vec::new();
    for (name, id) in matched.iter().zip(ids.iter()) {
        let allowed_ok = allowed.is_some_and(|a| a.contains(id));
        if py_str_strip_empty(name) || !remaining.contains(name) || !allowed_ok || existing.contains(id) {
            continue;
        }
        if let Some(pos) = remaining.iter().position(|n| n == name) {
            remaining.remove(pos);
        }
        existing.push(*id);
    }
    TaxonomyChoice { existing_ids: existing, new_names: remaining }
}

/// upstream `model_to_classification_suggestions(model, allowed_candidate_ids)`.
pub fn model_to_classification_suggestions(m: &ClassifierResponse, allowed: &AllowedIds) -> ClassificationSuggestions {
    ClassificationSuggestions {
        title: m.title.clone(),
        tags: choice(&m.tags, &m.matched_tags, &m.tag_ids, allowed.get("tags")),
        correspondents: choice(
            &m.correspondents,
            &m.matched_correspondents,
            &m.correspondent_ids,
            allowed.get("correspondents"),
        ),
        document_types: choice(
            &m.document_types,
            &m.matched_document_types,
            &m.document_type_ids,
            allowed.get("document_types"),
        ),
        storage_paths: choice(
            &m.storage_paths,
            &m.matched_storage_paths,
            &m.storage_path_ids,
            allowed.get("storage_paths"),
        ),
        dates: m.dates.clone(),
    }
}

/// upstream `classification_suggestions_to_model(suggestions)` (for localization).
pub fn classification_suggestions_to_model(s: &ClassificationSuggestions) -> ClassifierResponse {
    ClassifierResponse {
        title: s.title.chars().take(MAX_TITLE_LENGTH).collect(),
        tags: s.tags.new_names.iter().take(MAX_NEW_NAMES).cloned().collect(),
        correspondents: s.correspondents.new_names.iter().take(MAX_SINGLE_VALUE_NAMES).cloned().collect(),
        document_types: s.document_types.new_names.iter().take(MAX_SINGLE_VALUE_NAMES).cloned().collect(),
        storage_paths: s.storage_paths.new_names.iter().take(MAX_SINGLE_VALUE_NAMES).cloned().collect(),
        dates: s.dates.iter().take(MAX_DATES).cloned().collect(),
        ..Default::default()
    }
}

/// upstream `ai_classifier.parse_ai_response(raw)` – already typed here, hence identity.
pub fn parse_ai_response(s: ClassificationSuggestions) -> ClassificationSuggestions {
    s
}

/// Localization merge from `get_ai_document_classification`: `existing_ids` always
/// from the original, correspondents and dates never localized.
pub fn merge_localized(orig: &ClassificationSuggestions, loc: &ClassificationSuggestions) -> ClassificationSuggestions {
    let pick = |o: &TaxonomyChoice, l: &TaxonomyChoice| TaxonomyChoice {
        existing_ids: o.existing_ids.clone(),
        new_names: if l.new_names.is_empty() { o.new_names.clone() } else { l.new_names.clone() },
    };
    ClassificationSuggestions {
        title: if loc.title.is_empty() { orig.title.clone() } else { loc.title.clone() },
        tags: pick(&orig.tags, &loc.tags),
        correspondents: orig.correspondents.clone(),
        document_types: pick(&orig.document_types, &loc.document_types),
        storage_paths: pick(&orig.storage_paths, &loc.storage_paths),
        dates: orig.dates.clone(),
    }
}
